import re

from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand


class SwUpdate(GenericEMSSIMCommand):
    """Swupdate command class."""

    def __init__(self, connection, target, activate=None, loads_dir=None, prompt=None, newline_chars=None,
                 runner=None):
        """
        Swupdate command.

        :param connection: moler connection to device, terminal when command is executed.
        :param target: path to the TargetBD xml file (unpacked version) or load package zip file
        :param activate: flag for activation of just downloaded software bundle
        :param loads_dir: parent directory where enb builds are stored
        :param prompt: start prompt (on system where command ssh starts)
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SwUpdate, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.target = target
        self.activate = activate
        self.loads_dir = loads_dir

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd = "sw_update"
        if self.target:
            cmd = f"{cmd} {self.target}"
        if self.activate is not None:
            cmd = f"{cmd} {self.activate}"
        if self.loads_dir:
            cmd = f"{cmd} {self.loads_dir}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._operation_success(line)
                self._operation_failure(line)
                self._command_error(line)
            except ParsingDone:
                pass
            return super(SwUpdate, self).on_new_line(line, is_full_line)

    _re_success = re.compile(r"(?P<MSG>.*(Software\sUpdate\sprocedure\ssuccessfully\sfinished.*)|"
                             r"(Software\sUpdate\sOperation\sSUCCEEDED.*))", re.I)

    def _operation_success(self, line):
        """
        Check if operation succeeded.

        :param line: Line from device.
        :return: None.
        """
        if self._regex_helper.search_compiled(SwUpdate._re_success, line):
            self.current_ret['RESULT'] = self._regex_helper.group("MSG")
            raise ParsingDone

    _re_failure = re.compile(r"(?P<MSG>Software\sUpdate\sOperation\sFAILED.*)", re.I)

    def _operation_failure(self, line):
        """
        Check if operation failed.

        :param line: Line from device.
        :return: None.
        """
        if self._regex_helper.search_compiled(SwUpdate._re_failure, line):
            self.set_exception(CommandFailure(self, f"{self._regex_helper.group('MSG')}"))
            raise ParsingDone

    _re_error = re.compile(r".*ERROR:(?P<ERROR>.*)", re.I)

    def _command_error(self, line):
        """
        Catch errors.

        :param line: Line from device.
        :return: None.
        """
        if self._regex_helper.search_compiled(SwUpdate._re_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone


